import{_ as a,a0 as o,w as s,s as l,ao as c,I as n,x as r,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux script命令 —— 终端里的记录器 | LCTT x X-CMD","titleTemplate":false,"description":"Linux script命令 —— 终端里的记录器 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux script命令 —— 终端里的记录器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux script命令 —— 终端里的记录器 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140530 Linux script command--A recorder inside your Terminal","title":"Linux script命令 —— 终端里的记录器","tag":"201406","desc":""},"relativePath":"201406/20140530 Linux script command--A recorder inside your Terminal.md","filePath":"[post].md"}'),d={name:"201406/20140530 Linux script command--A recorder inside your Terminal.md"};function m(h,t,u,g,x,f){const i=o("Link");return s(),l("div",null,[t[11]||(t[11]=c(`<h1 id="linux-script命令-——-终端里的记录器" tabindex="-1">Linux script命令 —— 终端里的记录器 <a class="header-anchor" href="#linux-script命令-——-终端里的记录器" aria-label="Permalink to “Linux script命令 —— 终端里的记录器”">​</a></h1><p>当你在终端或者控制台工作时，你可能想要记录在终端中所做的一切。这些记录可以用来当作史料，保存终端所发生的一切。比如说，你和一些Linux管理员们同时管理着相同的机器，或者你让某人远程登陆到了你的服务器上，你可能记录想要终端里发生的一切。要实现这个目标，你可以使用script命令。</p><h3 id="script是什么" tabindex="-1">script是什么 <a class="header-anchor" href="#script是什么" aria-label="Permalink to “script是什么”">​</a></h3><p>scirpt就是一个命令，可以制作一份记录输出到终端的记录。对于那些想要真实记录终端会话的人来说，这很有用。该记录可以保存并在以后再打印出来。</p><h3 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to “怎么用”">​</a></h3><p>默认情况下，我们可以通过在终端中输入script来启动scirpt命令。</p><pre><code>pungki@dev-machine:~$ script
Script started, file is typescript
pungki@dev-machine:~$
</code></pre><p>你也可以指定目标文件名来记录打印结果。</p><pre><code>pungki@dev-machine:~$ script myfile
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/start_script.png" alt="Define script file"></p><p>当你再次见到命令提示符，这意味着终端将记录打印到终端的任何东西。</p><p>你会看到当前目录，有个名为myscript的文件。（LCTT译注，此处原文有误。这里指定了记录文件名为myfile，而不是默认的 typescript。）</p><h3 id="为什么我们要用script命令" tabindex="-1">为什么我们要用script命令 <a class="header-anchor" href="#为什么我们要用script命令" aria-label="Permalink to “为什么我们要用script命令”">​</a></h3><p>因为在之前已经提到过，script命令的主要功能是记录所有的东西。下面给出了两个使用该命令的场景。</p><h4 id="和同事共事时" tabindex="-1">和同事共事时 <a class="header-anchor" href="#和同事共事时" aria-label="Permalink to “和同事共事时”">​</a></h4><p>当和同事一起工作时，我们可以通过script来记录你的活动。</p><p>比如，我们会使用名为<strong>collaborate</strong>的打印文件，来完成打印：</p><pre><code>$ script collaborate
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/collaborate.png" alt="Create collaborate file"></p><p>然后，在完成一些任务后，假如你需要把你干的活发给另外一个工程师，那就把那文件发给他。所以当另外一个工程师需要复查所做的事情，他只要用文本编辑器打开这个文件就行了。</p><p>如果他想要更新该文件（以增加他的工作部分），可以使用<strong>-a</strong>选项。</p><pre><code>$ script -a collaborate
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/collaborate_append.png" alt="Append the file"></p><h4 id="记录某人在终端中的所作所为" tabindex="-1">记录某人在终端中的所作所为 <a class="header-anchor" href="#记录某人在终端中的所作所为" aria-label="Permalink to “记录某人在终端中的所作所为”">​</a></h4><p>你可能让你的工程师或者某个人远程访问你的系统，要确保你的工程师正在干正确的事，你可以记录下他在你系统上的所作所为。要让script命令在登录时自动运行，我们可以把它添加进shell环境配置文件中。如果你正在使用<strong>bash</strong> shell，把这一行加进你的bash环境配置文件中。</p><pre><code>$ vi ~/.profile

# run the script command to record everything
# use -q for quite and -a option to append the script
#
/usr/bin/script -qa /usr/local/script/log_record_script
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/script_login.png" alt="Add script to bash profile"></p><p>然后保存。下次他登录进你的系统时，script命令就会自动运行，并把日志记录进<strong>/usr/local/script/log_record_script</strong>。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/remote_script_quite.png" alt="Script without notification"></p><p><strong>-q</strong>选项可以让scirpt命令以静默模式运行，登录进来的用户不会知道script命令已经运行了。而<strong>-a</strong>选项将会让记录附加到文件中，而不会擦除先前的记录。</p><p>如果不使用<strong>-q</strong>选项，那么当用户登录进来时，他会收到像下图中这样的通知。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/remote_script.png" alt="Script with notification"></p><h3 id="退出记录" tabindex="-1">退出记录 <a class="header-anchor" href="#退出记录" aria-label="Permalink to “退出记录”">​</a></h3><p>要退出记录活动，我们可以在终端中按下<strong>Ctrl+D</strong>，或者输入<strong>exit</strong>。在退出script前，你会发现记录文件的大小为0 Kb，而在退出之后，文件大小会发生改变。</p><h3 id="结尾" tabindex="-1">结尾 <a class="header-anchor" href="#结尾" aria-label="Permalink to “结尾”">​</a></h3><p>Script命令在你需要记录或者存档终端活动时可能很有用，记录文件会存储为文本文件，所以可以很方便地用文本编辑器打开。跟平常一样，我们都可以通过输入<strong>man script</strong>或者<strong>scirpt -h</strong>来显示帮助页并查看更多详细用法。</p><hr>`,37)),n("p",null,[t[1]||(t[1]=r("via: ",-1)),e(i,{href:"http://linoxide.com/linux-command/script-command-recorder/"},{default:p(()=>[...t[0]||(t[0]=[r("http://linoxide.com/linux-command/script-command-recorder/",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=r("译者：",-1)),e(i,{href:"https://github.com/GOLinux"},{default:p(()=>[...t[2]||(t[2]=[r("GOLinux",-1)])]),_:1}),t[5]||(t[5]=r(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[r("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=r("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[r("LCTT",-1)])]),_:1}),t[9]||(t[9]=r(" 原创翻译，",-1)),e(i,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[r("Linux中国",-1)])]),_:1}),t[10]||(t[10]=r(" 荣誉推出",-1))])])}const _=a(d,[["render",m]]);export{L as __pageData,_ as default};
